p AS (SELECT 'usuario' tabla,CAST(id_usuario AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci id,'cuenta protegida' detalle FROM red_solidaria_test.usuario WHERE LOWER(correo)='nsm_26k@hotmail.com' OR admin_maestro=1 UNION SELECT 'rol',CAST(id_rol AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci,'rol protegido' FROM red_solidaria_test.usuario WHERE LOWER(correo)='nsm_26k@hotmail.com' OR admin_maestro=1 UNION SELECT 'permiso',CAST(rp.id_permiso AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci,'permiso asociado a rol protegido' FROM red_solidaria_test.rol_permiso rp JOIN red_solidaria_test.usuario u ON u.id_rol=rp.id_rol WHERE LOWER(u.correo)='nsm_26k@hotmail.com' OR u.admin_maestro=1)
SELECT 'REGISTRO_SINTETICO_PRESENTE' categoria,m0.tabla tabla,m0.id id,'clave historica' referencia,NULL tabla_relacionada,NULL id_relacionado,'Solo coincidencia de ID; verificar identidad actual' detalle,CONCAT(m0.fuente, ' | ', m0.escenario) fuente FROM m0 JOIN a ON a.tabla=m0.tabla AND a.id=m0.id CROSS JOIN contexto WHERE 1=1
UNION ALL
SELECT 'REGISTRO_SINTETICO_AUSENTE' categoria,m0.tabla tabla,m0.id id,'clave historica' referencia,NULL tabla_relacionada,NULL id_relacionado,'Ausente; no presupone causa' detalle,CONCAT(m0.fuente, ' | ', m0.escenario) fuente FROM m0 LEFT JOIN a ON a.tabla=m0.tabla AND a.id=m0.id CROSS JOIN contexto WHERE a.id IS NULL
UNION ALL
SELECT 'REFERENCIAS_ENTRANTES' categoria,e.padre tabla,e.id id,f.nombre referencia,e.hija tabla_relacionada,e.hijo id_relacionado,CASE WHEN h.id IS NULL THEN 'Hijo sin evidencia: investigar' ELSE 'Hijo con ID en manifiesto: verificar identidad' END detalle,NULL fuente FROM e JOIN f ON f.hija=e.hija AND f.columna=e.columna AND f.padre=e.padre AND f.colpadre=e.colpadre JOIN m ON m.tabla=e.padre AND m.id=e.id LEFT JOIN m h ON h.tabla=e.hija AND h.id=e.hijo CROSS JOIN contexto WHERE 1=1
UNION ALL
SELECT 'DEPENDENCIAS_COMPARTIDAS' categoria,e.padre tabla,e.id id,f.nombre referencia,e.hija tabla_relacionada,e.hijo id_relacionado,'Referencia de hijo no identificado en manifiestos' detalle,NULL fuente FROM e JOIN f ON f.hija=e.hija AND f.columna=e.columna AND f.padre=e.padre AND f.colpadre=e.colpadre JOIN m ON m.tabla=e.padre AND m.id=e.id LEFT JOIN m h ON h.tabla=e.hija AND h.id=e.hijo CROSS JOIN contexto WHERE h.id IS NULL
UNION ALL
SELECT 'REGISTRO_PROTEGIDO' categoria,p.tabla tabla,p.id id,'proteccion prioritaria' referencia,NULL tabla_relacionada,NULL id_relacionado,p.detalle detalle,NULL fuente FROM p CROSS JOIN contexto WHERE 1=1
UNION ALL
SELECT 'ORIGEN_O_DEPENDENCIA_NO_RESUELTA' categoria,f.padre tabla,NULL id,f.nombre referencia,f.hija tabla_relacionada,NULL id_relacionado,'FK real no modelada: revisar manualmente' detalle,NULL fuente FROM f LEFT JOIN k ON k.hija=f.hija AND k.columna=f.columna AND k.padre=f.padre AND k.colpadre=f.colpadre CROSS JOIN contexto WHERE k.hija IS NULL
UNION ALL
