SELECT 'ORIGEN_O_DEPENDENCIA_NO_RESUELTA' categoria,m0.tabla tabla,m0.id id,'identidad historica' referencia,NULL tabla_relacionada,NULL id_relacionado,'Contrastar procedencia, restauraciones, referencias y retencion' detalle,CONCAT(m0.fuente, ' | ', m0.escenario) fuente FROM m0 JOIN a ON a.tabla=m0.tabla AND a.id=m0.id CROSS JOIN contexto WHERE 1=1
UNION ALL
SELECT 'ORIGEN_O_DEPENDENCIA_NO_RESUELTA' categoria,'registro_auditoria' tabla,CAST(x.id_registro_auditoria AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci id,'JSON no exhaustivo' referencia,NULL tabla_relacionada,NULL id_relacionado,'Revisar rutas anidadas y entidades no modeladas' detalle,NULL fuente FROM red_solidaria_test.registro_auditoria x JOIN m ON m.tabla='registro_auditoria' AND m.id=CAST(x.id_registro_auditoria AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci CROSS JOIN contexto WHERE x.datos_nuevos IS NOT NULL OR x.datos_anteriores IS NOT NULL
UNION ALL
SELECT 'ORIGEN_O_DEPENDENCIA_NO_RESUELTA','donacion',m.id,'recepcion_operacion JSON','recepcion_operacion',CAST(r.id_recepcion_operacion AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci,'Revisar respuesta y respuesta_decision: sus referencias anidadas no se analizan','manifiesto' FROM red_solidaria_test.recepcion_operacion r JOIN m ON m.tabla='donacion' AND m.id=CAST(r.id_donacion AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci CROSS JOIN contexto WHERE r.respuesta IS NOT NULL OR r.respuesta_decision IS NOT NULL
UNION ALL
SELECT 'ORIGEN_O_DEPENDENCIA_NO_RESUELTA','registro_auditoria',CAST(x.id_registro_auditoria AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci,'auditoria JSON no exhaustivo',NULL,NULL,'Los campos JSON y entidades no mapeadas pueden referir otros registros; revisar manualmente','manifiesto' FROM red_solidaria_test.registro_auditoria x JOIN m ON m.tabla='registro_auditoria' AND m.id=CAST(x.id_registro_auditoria AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci CROSS JOIN contexto WHERE x.datos_anteriores IS NOT NULL OR x.datos_nuevos IS NOT NULL

UNION ALL
SELECT 'ORIGEN_O_DEPENDENCIA_NO_RESUELTA','usuario',NULL,'cuenta oficial',NULL,NULL,'Cuenta oficial ausente o no unica; no continuar con evaluaciones de limpieza',NULL FROM contexto WHERE (SELECT COUNT(*) FROM red_solidaria_test.usuario WHERE LOWER(correo)='nsm_26k@hotmail.com')<>1

ORDER BY categoria,tabla,id,tabla_relacionada,id_relacionado;
